#!/usr/bin/env node
// Phase 4 — write .gitattributes so Git LFS stores every video file. Images stay
// regular git blobs: hosts that build from the repo (e.g. Vercel without its Git
// LFS setting on) serve LFS pointer files instead, which breaks every <img>.
// Re-run after a re-capture, before `git add`.
import fs from 'node:fs';
import path from 'node:path';
import { ROOT } from './lib/config.mjs';

const VIDEO = ['mp4', 'webm', 'mov', 'm4v', 'ogv', 'avi', 'mkv'];

const lines = [
  '# Git LFS — generated by scripts/06-lfs-attributes.mjs',
  '# All video files (images are kept out of LFS so static hosts serve them):',
  ...VIDEO.flatMap((ext) => [`*.${ext} filter=lfs diff=lfs merge=lfs -text`, `*.${ext.toUpperCase()} filter=lfs diff=lfs merge=lfs -text`]),
  '',
];
fs.writeFileSync(path.join(ROOT, '.gitattributes'), lines.join('\n'));
console.log(`.gitattributes: LFS for ${VIDEO.length} video extensions; images stored as regular files`);
